// Generated Codex stand-in for Moguri tests. It speaks the `codex app-server` JSON-RPC protocol only;
// it never contacts OpenAI, reads credentials or runs a model.
import { appendFileSync, writeFileSync } from "node:fs";
import { spawn } from "node:child_process";
import { createInterface } from "node:readline";
import { join } from "node:path";
import { randomUUID } from "node:crypto";

const args = process.argv.slice(2);
const log = process.env.FAKE_CODEX_LOG;
const record = (value) => { if (log) appendFileSync(log, `${JSON.stringify(value)}\n`); };
record({ args, cwd: process.cwd(), env: Object.keys(process.env).filter((key) => key.startsWith("MOGURI") || key === "GITHUB_TOKEN") });
if (args[0] !== "app-server") { process.stderr.write("generated fake codex only serves app-server\n"); process.exit(2); }
const auth = process.env.FAKE_CODEX_AUTH ?? "chatgpt";
const write = (value) => process.stdout.write(`${JSON.stringify(value)}\n`);
const waiting = new Map();
let counter = 0, threadId = null, turnId = null, interrupted = null;
const ask = (method, params) => new Promise((resolve) => { const id = `fake_${++counter}`; waiting.set(id, resolve); write({ id, method, params }); });
const notify = (method, params) => write({ method, params: { threadId, turnId, ...params } });
const delay = (ms) => new Promise((resolve) => setTimeout(resolve, ms));
async function message(id, text) {
  notify("item/started", { item: { type: "agentMessage", id, text: "" } });
  notify("item/agentMessage/delta", { itemId: id, delta: text });
  notify("item/completed", { item: { type: "agentMessage", id, text } });
}
const command = (id, text, actions, status, extra = {}) => ({ type: "commandExecution", id, command: text, cwd: process.cwd(), commandActions: actions, status, ...extra });
async function scenario(request) {
  const cwd = process.cwd();
  if (request === "generated codex write") {
    await message("msg_1", "Writing the file.");
    const change = { type: "fileChange", id: "fc_1", changes: [{ path: join(cwd, "codex-output.txt"), kind: { type: "add" }, diff: "+generated by fake codex\n" }] };
    notify("item/started", { item: { ...change, status: "inProgress" } });
    const reply = await ask("item/fileChange/requestApproval", { itemId: "fc_1", threadId, turnId, reason: "generated write" });
    const accepted = reply?.decision === "accept";
    if (accepted) writeFileSync(join(cwd, "codex-output.txt"), "generated by fake codex\n");
    notify("item/completed", { item: { ...change, status: accepted ? "completed" : "declined" } });
    await message("msg_2", accepted ? "Generated Codex write complete." : "Generated Codex write was declined.");
  } else if (request === "generated codex command") {
    const reply = await ask("item/commandExecution/requestApproval", { itemId: "cmd_1", threadId, turnId, command: "npm test", cwd, startedAtMs: Date.now() });
    if (reply?.decision === "accept") {
      notify("item/started", { item: command("cmd_1", "npm test", [{ type: "unknown", command: "npm test" }], "inProgress") });
      notify("item/completed", { item: command("cmd_1", "npm test", [{ type: "unknown", command: "npm test" }], "completed", { aggregatedOutput: "generated tests passed", exitCode: 0 }) });
    } else notify("item/completed", { item: command("cmd_1", "npm test", [{ type: "unknown", command: "npm test" }], "declined") });
    await message("msg_3", reply?.decision === "accept" ? "Generated Codex command complete." : "Generated Codex command was declined.");
  } else if (request === "generated codex read") {
    const actions = [{ type: "read", command: "cat README.md", name: "README.md", path: "README.md" }];
    notify("item/started", { item: command("cmd_2", "cat README.md", actions, "inProgress") });
    notify("item/completed", { item: command("cmd_2", "cat README.md", actions, "completed", { aggregatedOutput: "generated readme", exitCode: 0 }) });
    await message("msg_4", "Generated Codex read complete.");
  } else if (request === "generated codex rogue") {
    notify("item/started", { item: { type: "mcpToolCall", id: "mcp_1", server: "generated", tool: "mutate", arguments: {}, status: "inProgress" } });
    notify("item/completed", { item: { type: "mcpToolCall", id: "mcp_1", server: "generated", tool: "mutate", arguments: {}, status: "completed", result: { content: [{ type: "text", text: "mutated" }] } } });
    await message("msg_5", "Generated Codex rogue complete.");
  } else if (request === "generated codex hang") {
    const orphan = spawn(process.execPath, ["-e", "setInterval(() => {}, 1000)"], { stdio: "ignore" });
    record({ orphan: orphan.pid });
    await message("msg_6", "Generated Codex is working.");
    await new Promise((resolve) => { interrupted = resolve; });
    return "interrupted";
  } else if (request === "generated codex fail") {
    notify("error", { error: { message: "generated upstream failure" }, willRetry: false });
    return "failed";
  } else await message("msg_7", `Generated Codex reply: ${request}`);
  notify("thread/tokenUsage/updated", { tokenUsage: { total: { inputTokens: 120, cachedInputTokens: 20, outputTokens: 30, reasoningOutputTokens: 5, totalTokens: 150 },
    last: { inputTokens: 120, cachedInputTokens: 20, outputTokens: 30, reasoningOutputTokens: 5, totalTokens: 150 }, modelContextWindow: 200000 } });
  return "completed";
}
createInterface({ input: process.stdin }).on("line", async (line) => {
  if (!line.trim()) return;
  const value = JSON.parse(line);
  if (value.id !== undefined && value.method === undefined) { waiting.get(value.id)?.(value.result); waiting.delete(value.id); return; }
  const { id, method, params = {} } = value;
  if (id === undefined) return;
  if (method === "initialize") write({ id, result: { userAgent: "codex_cli_rs/0.163.0 (Generated; arm64) moguri/test", codexHome: join(process.env.HOME ?? process.cwd(), ".codex"), platformFamily: "unix", platformOs: "macos" } });
  else if (method === "account/read") write({ id, result: auth === "none" ? { account: null, requiresOpenaiAuth: true } :
    { account: auth === "apiKey" ? { type: "apiKey" } : { type: "chatgpt", email: "generated@example.invalid", planType: "plus" }, requiresOpenaiAuth: true } });
  else if (method === "model/list") write({ id, result: params.cursor === "page-2" ?
    { data: [{ id: "gpt-generated-mini", model: "gpt-generated-mini", displayName: "GPT Generated Mini", description: "", hidden: false, isDefault: false }], nextCursor: null } :
    { data: [{ id: "gpt-generated", model: "gpt-generated", displayName: "GPT Generated", description: "", hidden: false, isDefault: true, inputModalities: ["text"] },
      { id: "hidden", model: "hidden-generated", displayName: "Hidden", description: "", hidden: true, isDefault: false }], nextCursor: "page-2" } });
  else if (method === "thread/start" || method === "thread/resume") {
    record({ method, params });
    threadId = method === "thread/resume" ? params.threadId : `thr_${randomUUID()}`;
    write({ id, result: { thread: { id: threadId }, model: params.model } });
  } else if (method === "turn/start") {
    const text = params.input?.[0]?.text ?? "";
    record({ method, prompt: text, sandboxPolicy: params.sandboxPolicy, approvalPolicy: params.approvalPolicy });
    turnId = `turn_${++counter}`;
    write({ id, result: { turn: { id: turnId, status: "inProgress" } } });
    const request = text.includes("Current request:\n") ? text.slice(text.lastIndexOf("Current request:\n") + 17) : text;
    if (request === "generated codex crash") process.exit(3);
    await delay(10);
    const status = await scenario(request);
    notify("turn/completed", { turn: { id: turnId, status, ...(status === "failed" ? { error: { message: "generated upstream failure" } } : {}) } });
  } else if (method === "turn/interrupt") {
    write({ id, result: {} });
    interrupted?.();
  } else write({ id, error: { code: -32601, message: `generated fake does not serve ${method}` } });
});
process.stdin.on("end", () => process.exit(0));
